import{_ as a,o as i,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-11-12","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-11-12","date":"2025-11-12T00:00:00.000Z","updated":"2025-12-04T00:00:00.000Z","tags":["Ceph","RGW","KMS","Key Management","Cache Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-11-12.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-11-12.md","lastUpdated":1780460162000}'),o={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-11-12.md"};function r(n,e,c,p,s,d){return i(),t("div",null,[...e[0]||(e[0]=[l('<h3 id="ceph-rgw-refactoring-meeting-2025-11-12-改进总结" tabindex="-1">Ceph RGW Refactoring Meeting 2025-11-12 改进总结 <a class="header-anchor" href="#ceph-rgw-refactoring-meeting-2025-11-12-改进总结" aria-label="Permalink to &quot;Ceph RGW Refactoring Meeting 2025-11-12 改进总结&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><p>本次会议主要讨论了 Ceph RGW（RADOS Gateway）中 SSC KMS（Secret Store Cache Key Management System）密钥缓存的改进方案，重点关注缓存的生命周期管理、运行时配置及代码结构优化。</p><h4 id="关键讨论点" tabindex="-1">关键讨论点 <a class="header-anchor" href="#关键讨论点" aria-label="Permalink to &quot;关键讨论点&quot;">​</a></h4><ol><li><p><strong>缓存生命周期管理问题</strong></p><ul><li>当前缓存使用静态变量形式，与 RGW 其他组件的生命周期管理不一致。</li><li>讨论是否应在 <code>app_main</code> 中初始化和销毁缓存，以及是否允许在 <code>rgw-admin</code> 中使用缓存。</li><li>决定优先在 <code>app_main</code> 中初始化缓存，并通过 <code>req_state</code> 传递至 KMS 层，暂不支持 <code>rgw-admin</code>。</li></ul></li><li><p><strong>运行时缓存启用的可行性</strong></p><ul><li>讨论了在 Linux 内核密钥存储配额调整后重新启用缓存的需求场景。</li><li>提出通过 <code>req_state</code> 持有缓存的共享指针，旧请求可继续使用原有缓存实例，并支持通过 <code>config observer</code> 监听配置变更，动态启停缓存。</li></ul></li><li><p><strong>代码结构优化</strong></p><ul><li>当前 KMS 逻辑与缓存逻辑耦合度高，难以维护。</li><li>讨论将缓存相关代码抽离至独立文件，仅保留核心接口，确保 <code>app_main</code> 仅依赖缓存模块而非整个 KMS。</li></ul></li><li><p><strong>运维与文档增强</strong></p><ul><li>文档化默认缓存大小与内核配额的关系，补充监控指南。</li><li>计划通过 Prometheus 监控密钥存储错误指标，并收集用户实践后提交补充文档。</li></ul></li></ol><h4 id="决议事项" tabindex="-1">决议事项 <a class="header-anchor" href="#决议事项" aria-label="Permalink to &quot;决议事项&quot;">​</a></h4><ol><li><p><strong>代码改进</strong></p><ul><li>将缓存生命周期绑定至 <code>app_main</code>，通过 <code>req_state</code> 传递。</li><li>分离 KMS 与缓存逻辑，提升代码可读性。</li></ul></li><li><p><strong>功能增强</strong></p><ul><li>支持运行时缓存启用（非强制，后续优化）。</li></ul></li><li><p><strong>文档补充</strong></p><ul><li>完善内核配额配置说明，后续添加监控最佳实践。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>提交代码重构（生命周期管理/结构优化）由 Marcel 负责，下周完成。</li><li>提供性能基准测试数据由 Marcel 负责，近期完成。</li><li>补充运维监控文档（Prometheus 集成）由 Marcel 负责，用户测试后完成。</li></ul><p>本次会议讨论了 Ceph RGW 中 SSC KMS 密钥缓存的改进方案，包括生命周期管理、运行时配置和代码结构优化等方面，并制定了相应的改进计划和后续行动。</p>',10)])])}const _=a(o,[["render",r]]);export{h as __pageData,_ as default};
